import type { DeckCard, DeckIndexEntry } from "./types"

const DECKS_URL = `${import.meta.env.BASE_URL}decks`

async function getJson<T>(url: string): Promise<T> {
  const res = await fetch(url)
  if (!res.ok) throw new Error(`Could not load ${url} (${res.status})`)
  return (await res.json()) as T
}

/** Built-in decks list (generated by `npm run decks`). */
export function fetchDeckIndex(): Promise<DeckIndexEntry[]> {
  return getJson<DeckIndexEntry[]>(`${DECKS_URL}/index.json`)
}

/** All cards of one built-in deck. */
export function fetchDeckCards(deckId: string): Promise<DeckCard[]> {
  return getJson<DeckCard[]>(`${DECKS_URL}/${encodeURIComponent(deckId)}.json`)
}
